/**
 * Vendor the Relay design tokens (CSS custom properties) into the Relay docs
 * theme. Relay is the published reference for the dashboard's primitives; do
 * not edit the generated file by hand. Fix tokens upstream in the dashboard,
 * re-vendor them into Relay, then re-run this script.
 *
 * Run: RELAY_DIR=../relay bun run scripts/sync-relay-tokens.ts
 * Writes .vitepress/theme-relay/tokens.css and provenance.json.
 */
import { readFileSync, writeFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { execFileSync } from "node:child_process";
import { join, resolve } from "node:path";

const RELAY_DIR = resolve(process.env.RELAY_DIR || "../relay");
const SOURCE = "src/vendor/dashboard-globals.css";
const OUT_DIR = resolve(".vitepress/theme-relay");

const css = readFileSync(join(RELAY_DIR, SOURCE), "utf8");
const revision = execFileSync("git", ["-C", RELAY_DIR, "rev-parse", "HEAD"], { encoding: "utf8" }).trim();

/** Custom properties declared directly inside the first `<selector> {` block. */
function block(selector: string): string[] {
  const start = css.search(new RegExp(`^\\s*${selector.replace(".", "\\.")}\\s*\\{`, "m"));
  if (start < 0) throw new Error(`No ${selector} block in ${SOURCE}`);
  let depth = 0;
  let i = css.indexOf("{", start);
  const open = i;
  for (; i < css.length; i++) {
    if (css[i] === "{") depth++;
    else if (css[i] === "}" && --depth === 0) break;
  }
  const body = css.slice(open + 1, i).replace(/\/\*[\s\S]*?\*\//g, "");
  return [...body.matchAll(/(--[a-z0-9-]+)\s*:\s*([^;]+);/gi)].map((m) => `  ${m[1]}: ${m[2].trim()};`);
}

const light = block(":root");
const dark = block(".dark");

const out = `/* Generated by scripts/sync-relay-tokens.ts from linkrunner-labs/relay
 * ${SOURCE} @ ${revision}. Do not edit by hand. */
:root {
${light.join("\n")}
}

.dark {
${dark.join("\n")}
}
`;

writeFileSync(join(OUT_DIR, "tokens.css"), out);
writeFileSync(
  join(OUT_DIR, "provenance.json"),
  JSON.stringify(
    {
      repository: "https://github.com/linkrunner-labs/relay",
      revision,
      source: SOURCE,
      sha256: createHash("sha256").update(css).digest("hex"),
      target: ".vitepress/theme-relay/tokens.css",
    },
    null,
    2
  ) + "\n"
);
console.log(`Wrote ${light.length} light and ${dark.length} dark tokens from relay@${revision.slice(0, 7)}.`);
